/**
 * Material Symbols 字形转成的 [ImageVector]（实例化到 wght=350 / opsz=24 / FILL=0）。
 *
 * 为什么不用图标字体直接画文本：字体是按 ascent/descent 排版，图标字体的垂直度量极不对称
 * （ascent 1.1em、descent 0.1em），文本方式在不同行高下会偏移，做不到和现有 ImageVector 图标
 * 一样"天生居中"。转成矢量后与 `ThinActionIcons` / `MiuixIcons` 同构：24 单位视口、墨迹居中、
 * 尺寸与颜色完全可控。
 *
 * 名字沿用 Compose 图标名（`Icons.Default.Add` → `"Add"`）。**改整体粗细** = 改下面的字重重新生成：
 * 生成脚本用 fontTools 把 Material Symbols 可变字体实例化到目标 wght，再按 24/960 缩放到 24 单位视口。
 *
 * 字形来源：Google Material Symbols（Apache-2.0）。
 */
internal object MaterialSymbolVectors {

    /** 生成时使用的 Material Symbols 字重；改它必须重新生成本文件。 */
    const val WEIGHT: Int = 350

    private fun icon(name: String, pathData: String): ImageVector =
        ImageVector.Builder(
            name = "Symbols$name",
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f,
        ).apply {
            addPath(
                pathData = PathParser().parsePathString(pathData).toNodes(),
                fill = SolidColor(Color.White),
            )
        }.build()

    private val icons: Map<String, ImageVector> by lazy {
        paths.mapValues { (name, path) -> icon(name, path) }
    }

    fun get(name: String): ImageVector? = icons[name]

